css:
.resume{max-width: 210mm;
      width: 100%;
      background: #ffffff;
      box-shadow: 0 12px 30px rgba(0, 0, 0, 0.15);
      border-radius: 2px;
      overflow: hidden;
      transition: all 0.2s;}
.resume-inner{padding: 1.2in 0.85in 1.0in 0.85in;}
.resume h1, .resume h2, .resume h3, .resume p, .resume ul, .resume li, .resume div, .resume span{font-weight: normal;
      text-rendering: optimizeLegibility;}
.name{font-family: 'Helvetica Neue', 'Helvetica', 'Arial', sans-serif;
      font-weight: 700;
      font-size: 32pt;
      letter-spacing: 1.2px;
      color: #0a0f1c;
      margin-bottom: 0.1in;
      line-height: 1.1;
      border-bottom: 2.5px solid #2c3e50;
      padding-bottom: 0.15in;
      display: inline-block;
      width: 100%;}
.title-line{font-family: 'Arial', 'Helvetica', '思源黑体', sans-serif;
      font-size: 13pt;
      font-weight: 500;
      color: #2c3e50;
      margin-top: 0.08in;
      margin-bottom: 0.45in;
      letter-spacing: 0.8px;
      text-transform: uppercase;
      word-spacing: 2px;}
.contact-info{display: flex;
      flex-wrap: wrap;
      gap: 0.4in 0.6in;
      margin-bottom: 0.45in;
      font-size: 10.5pt;
      color: #1e293b;
      font-weight: 400;
      border-bottom: 1px solid #d1d5db;
      padding-bottom: 0.3in;}
.contact-item{display: flex;
      align-items: center;
      gap: 6px;
      white-space: nowrap;}
.contact-icon{font-weight: 600;
      color: #1e3a5f;
      font-size: 10pt;
      width: 18px;
      display: inline-block;
      text-align: left;}
.section-title{font-family: 'Helvetica Neue', 'Helvetica', 'Arial', sans-serif;
      font-weight: 700;
      font-size: 13pt;
      letter-spacing: 1.8px;
      color: #0b1c2e;
      text-transform: uppercase;
      margin-top: 0.45in;
      margin-bottom: 0.18in;
      border-left: 4px solid #2c3e50;
      padding-left: 12px;
      line-height: 1.3;}
.divider-light{height: 1px;
      background: #e2e8f0;
      margin: 0.05in 0 0.18in 0;
      width: 100%;}
.entry{margin-bottom: 0.22in;}
.entry-header{display: flex;
      justify-content: space-between;
      align-items: baseline;
      flex-wrap: wrap;
      margin-bottom: 0.06in;}
.institution{font-weight: 700;
      font-size: 12pt;
      color: #0f172a;
      font-family: 'Helvetica Neue', 'Arial', sans-serif;}
.role{font-weight: 600;
      font-size: 11pt;
      color: #1e293b;
      margin-left: 0.15in;
      font-style: normal;}
.date-location{font-weight: 400;
      font-size: 10pt;
      color: #4b5563;
      text-align: right;
      white-space: nowrap;
      letter-spacing: 0.3px;}
.desc-list{list-style: none;
      margin-top: 0.08in;
      padding-left: 0.15in;}
.desc-list li{font-size: 10.5pt;
      color: #1f2937;
      margin-bottom: 0.07in;
      position: relative;
      padding-left: 0.2in;
      line-height: 1.45;}
.desc-list li::before{content: "•";
      position: absolute;
      left: 0;
      color: #1e3a5f;
      font-weight: bold;
      font-size: 10pt;}
.skills-container{display: flex;
      flex-wrap: wrap;
      gap: 0.18in 0.4in;
      margin-top: 0.08in;}
.skill-group{font-size: 10.5pt;
      color: #0f172a;}
.skill-label{font-weight: 700;
      color: #1e293b;
      margin-right: 4px;}
.skill-items{color: #2d3748;}
.cert-item{display: flex;
      justify-content: space-between;
      font-size: 10.5pt;
      margin-bottom: 0.07in;}
.cert-name{font-weight: 600;
      color: #0f172a;}
.cert-detail{color: #4b5563;}
.edu-entry{display: flex;
      justify-content: space-between;
      align-items: baseline;
      margin-bottom: 0.08in;}
.edu-school{font-weight: 700;
      font-size: 11pt;
      color: #0f172a;}
.edu-degree{font-weight: 500;
      color: #1e293b;
      margin-left: 0.15in;}
.project-title{font-weight: 700;
      font-size: 11pt;
      color: #0f172a;}
.project-stack{font-weight: 400;
      color: #4b5563;
      font-size: 10pt;
      margin-left: 0.15in;}
.footer-note{margin-top: 0.3in;
      font-size: 9pt;
      color: #9ca3af;
      border-top: 1px solid #e5e7eb;
      padding-top: 0.15in;
      text-align: left;}

.resume{font-family:Arial,"Helvetica","思源黑体","Source Han Sans SC",sans-serif;color:#1f2937;line-height:1.5}.skill-group{margin-bottom:8px}.skill-group .skill-items{margin-left:4px}
